open.example:
// client
const { Book } = kcds.ui;

const bookId = Book.open({
  style: 'letter',
  pages: ['To the burgrave,\nthe grain did not arrive.'],
});
if (bookId === null) {
  console.log(Book.lastFailure());
}

open.exampleCs:
// client

var bookId = Book.Open(new { style = "letter", pages = new[] { "To the burgrave,\nthe grain did not arrive." } });
if (bookId == null)
{
    Log.Info(Book.LastFailure());
}

currentBook.example:
// client
const { Book } = kcds.ui;

if (Book.currentBook() !== null) {
  Book.close();
}

lastFailure.example:
// client
const { Book } = kcds.ui;

if (Book.open({ pages: ['...'] }) === null) {
  console.log(Book.lastFailure());
}

lastFailure.exampleCs:
// client

if (Book.Open(new { pages = new[] { "..." } }) == null)
{
    Log.Info(Book.LastFailure());
}

image.example:
// client
const { Book } = kcds.ui;

const crest = Book.image('ui/crest.dds');
Book.open({ style: 'letter', pages: ['By order of the burgrave'], images: [{ page: 0, image: crest }] });

image.exampleCs:
// client

var crest = Book.Image("ui/crest.dds");
Book.Open(new { style = "letter", pages = new[] { "By order of the burgrave" }, images = new object[] { new { page = 0, image = crest } } });
